ACTIVE = None
def select(name="ieee69"):
    """Bind module globals to the chosen dataset (affects all downstream modules)."""
    global ACTIVE, LINES, LOAD_P, LOAD_Q, TIE_SWITCHES, CRITICAL_BUSES
    global CUSTOMERS, TOTAL_CUSTOMERS, N_BUSES, CLUSTER_KS
    d = _DATA[name]; ACTIVE = name
    LINES = [tuple(l) for l in d["LINES"]]
    LOAD_P = d["LOAD_P"]; LOAD_Q = d["LOAD_Q"]
    TIE_SWITCHES = [tuple(t) for t in d["TIE_SWITCHES"]]
    CRITICAL_BUSES = set(d["CRITICAL_BUSES"])
    CUSTOMERS = d["CUSTOMERS"]; TOTAL_CUSTOMERS = sum(CUSTOMERS)
    N_BUSES = len(LOAD_P); CLUSTER_KS = d["CLUSTER_KS"]
    global TOTAL_P
    TOTAL_P = sum(LOAD_P)

def downstream_buses(failed_line):
    """Buses de-energized when `failed_line` fails (component cut from bus 1)."""
    import networkx as nx
    g = nx.Graph()
    for (u, v, *_r) in LINES:
        if (u, v) != failed_line and (v, u) != failed_line:
            g.add_edge(u, v)
    g.add_nodes_from(range(1, N_BUSES + 1))
    alive = nx.node_connected_component(g, 1) if 1 in g else set()
    return set(range(1, N_BUSES + 1)) - set(alive)

select("ieee69")


def build_graph(include_ties=False):
    """NetworkX graph of the active grid (optionally with tie lines)."""
    import networkx as nx
    g = nx.Graph()
    g.add_nodes_from(range(1, N_BUSES + 1))
    for (u, v, *_r) in LINES:
        g.add_edge(u, v)
    if include_ties:
        for (u, v) in TIE_SWITCHES:
            g.add_edge(u, v)
    return g
